"use strict";(self.webpackChunklearn_programming=self.webpackChunklearn_programming||[]).push([[8262],{20020:e=>{e.exports=JSON.parse('{"pluginId":"fundamentals","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Fundamentals","href":"/es/fundamentals/intro","docId":"intro","unlisted":false},{"type":"category","label":"Computer Engineering","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Computer Engineering","href":"/es/fundamentals/computer-engineering/intro","docId":"computer-engineering/intro","unlisted":false},{"type":"category","label":"lesson-notes","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"CPU Pipeline Stages","href":"/es/fundamentals/computer-engineering/lesson-notes/cpu-pipeline","docId":"computer-engineering/lesson-notes/cpu-pipeline","unlisted":false},{"type":"link","label":"Cache Hierarchy","href":"/es/fundamentals/computer-engineering/lesson-notes/cache-hierarchy","docId":"computer-engineering/lesson-notes/cache-hierarchy","unlisted":false},{"type":"link","label":"Branch Prediction","href":"/es/fundamentals/computer-engineering/lesson-notes/branch-prediction","docId":"computer-engineering/lesson-notes/branch-prediction","unlisted":false}]}]},{"type":"category","label":"Algorithms","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Algorithms","href":"/es/fundamentals/algorithms/intro","docId":"algorithms/intro","unlisted":false}]},{"type":"category","label":"Graphics","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Graphics","href":"/es/fundamentals/graphics/intro","docId":"graphics/intro","unlisted":false}]},{"type":"category","label":"Concurrency","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Concurrency","href":"/es/fundamentals/concurrency/intro","docId":"concurrency/intro","unlisted":false}]},{"type":"category","label":"Artificial Intelligence","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Artificial Intelligence","href":"/es/fundamentals/artificial-intelligence/intro","docId":"artificial-intelligence/intro","unlisted":false}]}]},"docs":{"algorithms/intro":{"id":"algorithms/intro","title":"Algorithms","description":"Algorithm design is about choosing the right strategy \u2014 not just getting a correct answer, but getting it efficiently at scale. This section covers the core analysis tools, design patterns, and data structures that appear everywhere from interview questions to production systems.","sidebar":"tutorialSidebar"},"artificial-intelligence/intro":{"id":"artificial-intelligence/intro","title":"Artificial Intelligence","description":"From classic search algorithms to modern transformers, this section builds up the theory and intuition behind AI systems \u2014 with interactive visualizers for the parts that are hardest to grasp from equations alone.","sidebar":"tutorialSidebar"},"computer-engineering/intro":{"id":"computer-engineering/intro","title":"Computer Engineering","description":"This section covers the hardware-level foundations of how computers work \u2014 from individual transistors up through the operating system.","sidebar":"tutorialSidebar"},"computer-engineering/lesson-notes/branch-prediction":{"id":"computer-engineering/lesson-notes/branch-prediction","title":"Branch Prediction","description":"When a CPU encounters a branch instruction (if, loop condition, function call), it doesn\'t yet know which path to follow \u2014 the branch condition is computed several pipeline stages later. But the CPU can\'t pause: a stalled pipeline wastes cycles.","sidebar":"tutorialSidebar"},"computer-engineering/lesson-notes/cache-hierarchy":{"id":"computer-engineering/lesson-notes/cache-hierarchy","title":"Cache Hierarchy","description":"CPUs can execute instructions billions of times per second. Main memory (DRAM) takes ~200 CPU cycles to respond to a request. Without caches, your CPU would sit idle 99% of the time, waiting for data.","sidebar":"tutorialSidebar"},"computer-engineering/lesson-notes/cpu-pipeline":{"id":"computer-engineering/lesson-notes/cpu-pipeline","title":"CPU Pipeline Stages","description":"Modern CPUs don\'t execute one instruction completely before starting the next. Instead, they overlap execution using a pipeline \u2014 the same way an assembly line lets a car factory build multiple cars simultaneously, each at a different station.","sidebar":"tutorialSidebar"},"concurrency/intro":{"id":"concurrency/intro","title":"Concurrency","description":"Concurrency is one of the hardest topics in software engineering \u2014 bugs are non-deterministic, hard to reproduce, and can lie dormant for years. This section covers the primitives, patterns, and mental models needed to write correct concurrent code.","sidebar":"tutorialSidebar"},"graphics/intro":{"id":"graphics/intro","title":"Graphics","description":"Computer graphics turns math into pixels. Whether you\'re writing a game engine, a data visualizer, or a UI renderer, understanding how the GPU pipeline works lets you write faster shaders, avoid driver pitfalls, and reason about visual artifacts.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Fundamentals","description":"Deep dives into the underlying systems that every software engineer should understand \u2014 hardware behavior, algorithm design, rendering pipelines, concurrent execution, and machine learning.","sidebar":"tutorialSidebar"}}}')}}]);